"""CLAREO, IMPORTER, STAND 64 — vrais PDF (jamais vérifiés avant cette session : code écrit avant la règle d'or, désormais confronté au réel). Les 3 totaux retombent exactement sur le Total HT affiché par chaque PDF."""

from moteur.lecture_pdf import lire_pdf
from moteur.modele import Article
from moteur.detecteur import detecter_fournisseur
from moteur.fournisseurs.clareo import parse_clareo
from moteur.fournisseurs.importer import parse_importer
from moteur.fournisseurs.stand64 import parse_stand64

from conftest import FIXTURES


def _texte(nom):
    return lire_pdf(FIXTURES / nom)


def test_detection():
    assert detecter_fournisseur(_texte("clareo.pdf")) == "CLAREO"
    assert detecter_fournisseur(_texte("importer.pdf")) == "IMPORTER"
    assert detecter_fournisseur(_texte("stand64.pdf")) == "STAND 64"


